  private static void add(String dest,String name,String desc,int price,String hours,String category,String slot){ String id=dest+"-"+name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-"); BY_DESTINATION.computeIfAbsent(dest,k->new ArrayList<>()).add(new ActivityItem(id,dest,name,desc,BigDecimal.valueOf(price),new BigDecimal(hours),category,slot)); }
  public static List<ActivityItem> forDestination(String destinationId){ return List.copyOf(BY_DESTINATION.getOrDefault(destinationId,List.of())); }
  public static Map<String,List<ActivityItem>> all(){ return Collections.unmodifiableMap(BY_DESTINATION); }
